#include <iostream>
#include <string>

struct Enemy
{
    std::string name;
    int hp;
};

void heal(int& hp) { hp += 10; }

void hitTarget(Enemy* target, int dmg)
{
    if (!target) return;        // no target: do nothing
    target->hp -= dmg;          // -> follows the pointer, then picks a field
}

int main()
{
    int ammo = 30;
    int* p = &ammo;
    *p = 25;
    std::cout << "ammo " << ammo << "\n";

    Enemy goblin{"Goblin", 30};
    Enemy* target = &goblin;
    hitTarget(target, 12);
    heal(goblin.hp);
    std::cout << goblin.name << " has " << goblin.hp << " HP\n";

    target = nullptr;           // lost the target
    hitTarget(target, 99);      // safe: the function checks
    std::cout << "still " << goblin.hp << " HP\n";
    return 0;
}

