void addAmmoRef(int& ammo, int n)
{
    ammo += n;
    if (ammo > 99) ammo = 99;
}

// a pointer can be null, so check before following it
bool addAmmoPtr(int* ammo, int n)
{
    if (!ammo) return false;
    addAmmoRef(*ammo, n);   // *ammo is the int itself
    return true;
}

