exercises.solution:
#include <string>
#include <vector>

struct Enemy
{
    std::string name;
    int hp;
};

Enemy* lockOn(std::vector<Enemy>& enemies, const std::string& name)
{
    for (Enemy& e : enemies)       // & : the real item, not a copy
        if (e.name == name) return &e;
    return nullptr;                // no such enemy
}

bool shoot(Enemy* target, int dmg)
{
    if (!target) return false;
    target->hp -= dmg;
    if (target->hp < 0) target->hp = 0;
    return true;
}
